import {evidenceUI,usd,number} from './evidence-ui.js';
let architecture='optimized',condition='operating',month='2026-11',workload='consent-changes',dimension='demand_percent',trial='transient-recovery';
const labels={reference:'Reference · mixed routes',optimized:'Optimized · operating cost',resilient:'Resilient · disruption envelope'};
export function economicsMetrics(read,metric){const p=read('projection.json');return [metric('Annual source events',number(p.annual_source_events),'Modeled synthetic demand · not a load test'),metric('Operating optimum',usd(p.alternatives.optimized.annual_cents.operating),'Synthetic annual USD planning cost'),metric('Resilient operating year',usd(p.alternatives.resilient.annual_cents.operating),'Pays more now; lower modeled disruption cost'),metric('Bounded HTTP trials',p.http_trials.length,'Separate local execution · rejected outcomes retained')];}
export function economicsPanel(ui){const {el,json:read,facts,finding}=ui,{section,inspect,choose,table,origin,stages}=evidenceUI(ui),d=read('decision.json'),spec=read('scenario.json'),p=read('projection.json');
 const root=el('div',undefined,'economics-investigation release-investigation');const hero=el('div',undefined,'release-hero');hero.append(el('small','ENTERPRISE INTEGRATION ECONOMICS · SYNTHETIC USD','release-kicker'),el('h2','Which architecture is worth operating?'),el('p','1.2 billion annual source events. Eight workloads. Compare shared costs, throughput constraints and consent requirements before choosing the cheapest feasible design.'));root.append(hero);
 const controls=(all=true)=>{const c=el('div',undefined,'economics-controls');c.append(choose('Architecture','economics-architecture',Object.entries(labels),architecture,v=>{architecture=v;rerender();}));if(all)c.append(choose('Operating condition','economics-condition',spec.conditions.map(c=>[c.id,c.id]),condition,v=>{condition=v;rerender();}),choose('Billing month','economics-month',spec.months.map(m=>[m.id,m.id]),month,v=>{month=v;rerender();}));return c;};
 let rerender=()=>{};
 stages(root,[['decision','01 · Architecture decision'],['cost','02 · Cost & capacity'],['sensitivity','03 · Sensitivity'],['execution','04 · Bounded HTTP execution']], 'decision', stage=>{
  const wrapper=el('div');const render=()=>{wrapper.replaceChildren();
  if(stage==='decision'){
   const box=section('An operating optimum is not the resilient optimum.');box.append(el('p','All prices are synthetic planning assumptions. The disruption column is an alternative modeled year, never an added expense or an observed incident.'));
   box.append(table(['Architecture','Operating year','Disruption year','Workers'],Object.entries(labels).map(([key,label])=>[label,usd(p.alternatives[key].annual_cents.operating),usd(p.alternatives[key].annual_cents['campaign-disruption']),p.alternatives[key].workers]),'Same workload and price book · annual modeled USD'));
   box.append(finding('A quantified tradeoff, not realized savings','Operating optimization reduces modeled cost by '+usd(p.alternatives.reference.annual_cents.operating-p.alternatives.optimized.annual_cents.operating)+'. Resilience adds '+usd(p.alternatives.resilient.annual_cents.operating-p.alternatives.optimized.annual_cents.operating)+' in the operating year and reduces disruption-year cost by '+usd(p.alternatives.optimized.annual_cents['campaign-disruption']-p.alternatives.resilient.annual_cents['campaign-disruption'])+'.'));
   box.append(controls(false));const choice=d.alternatives[architecture];box.append(table(['Workload / business purpose','Selected route','Required freshness'],spec.workloads.map(w=>[w.purpose,choice.selection.routes[w.id],w.max_lag_minutes+' minutes']),labels[architecture]+' · selected routes'));
   box.append(el('p','The operating optimum shares event-fabric capacity across all eight routes. The resilient design microbatches seven workloads while consent suppression keeps its one-minute streaming requirement. CRM quota, capability and permitted-region constraints remain enforced.'));
   inspect(box,'Inspect declared requirements and route options',spec.workloads);inspect(box,'Inspect recorded solver and independent finite oracle',d.independent_oracles);box.append(origin('scenario.json','Open versioned demand and synthetic price book'));wrapper.append(box);
  }else if(stage==='cost'){
   const box=section('Follow source events through requests to the bill.');box.append(controls());
   const assessment=d.alternatives[architecture].assessment,report=assessment.conditions.find(c=>c.id===condition),m=report.months.find(m=>m.id===month);
   box.append(facts([['Monthly cost',usd(m.cost_cents)],['Annual cost · selected envelope',usd(report.annual_cents)],['Shared work units / hour',number(m.shared_work.used)+' / '+number(m.shared_work.limit)],['CRM requests / hour',number(m.crm_quota.used)+' / '+number(m.crm_quota.limit)]]));
   box.append(table(['Cost component','USD / selected month'],Object.entries(m.components_cents).map(([k,v])=>[k.replaceAll('_',' '),usd(v)]),'Integer-cent components · shared subscriptions charged once'));
   box.append(choose('Inspect a workload','economics-workload',spec.workloads.map(w=>[w.id,w.purpose]),workload,v=>{workload=v;render();}));const row=m.lines.find(r=>r.workload===workload),w=spec.workloads.find(w=>w.id===workload),r=w.options.find(o=>o.id===row.route);
   box.append(table(['Source events','Downstream records','Emission windows','Batches','Retries','Total attempts'],[[row.source_events,row.downstream_records,row.emission_windows,row.batches,row.retry_requests,row.attempts].map(number)],workload+' · fan-out and partial batches change request demand'));
   box.append(el('p','Source × seasonal demand × condition demand is rounded up to integer events. Fan-out creates downstream records. Balanced peak/off-peak emission windows determine partial batches; retries increase attempts. Fixed costs and shared overage are allocated by record volume.'));
   inspect(box,'Inspect exact workload calculation and rates',{requirement:w,selected_route:r,condition:spec.conditions.find(c=>c.id===condition),monthly_line:row});inspect(box,'Inspect all monthly allocations',m);
   box.append(finding('Capacity is declared and modeled','The worker limit reserves 20% headroom. Hourly balanced emission and declared route lag do not prove queue-tail latency, arbitrary synchronized burst handling or strict rolling-arrival API compliance.'));box.append(origin('decision.json','Open exact monthly cost and capacity records'));wrapper.append(box);
  }else if(stage==='sensitivity'){
   const box=section('When would the architecture decision change?');box.append(choose('Sensitivity dimension','economics-dimension',[...new Set(d.sensitivity.map(s=>s.dimension))].map(s=>[s,s.replaceAll('_',' ')]),dimension,v=>{dimension=v;render();}));const selected=d.sensitivity.filter(s=>s.dimension===dimension);
   box.append(el('p','These are recorded parameter sweeps, not a live solver or arbitrary forecast. Demand, quota, processing price, worker capacity and freshness were varied independently. Every recorded optimum agrees with a separate bounded enumeration.'));
