   inspect(box,'Inspect exact sweep selections and input identities',selected);inspect(box,'Inspect infeasible one-cent budget reduction',d.budget_rejection);box.append(origin('decision.json','Open complete recorded sensitivity results'));wrapper.append(box);
  }else{
   const box=section('An inexpensive incomplete run still fails acceptance.');box.append(el('p','This is separate, bounded local HTTP execution on an accelerated clock with SQLite and synthetic prices. It is not a 1.2-billion-event load test, vendor integration or enterprise timing projection.'));
   box.append(choose('Inspect a recorded HTTP trial','economics-trial',p.http_trials.map(t=>[t.name,t.name+' · '+(t.acceptable?'accepted':'rejected')]),trial,v=>{trial=v;render();}));const t=p.http_trials.find(t=>t.name===trial),result=read('http/'+trial+'-result.json');
   box.append(facts([['Acceptance',t.acceptable?'Accepted in bounded local fixture':'Rejected · findings remain visible'],['Source records',number(t.source_records)],['On-time records',number(t.on_time_records)],['Late / unresolved',number(t.late_records)+' / '+number(t.unresolved_records)],['Actual synthetic execution cost',usd(t.actual_synthetic_cost_cents)]]));
   box.append(table(['Trial','Decision','Source','On time','Late','Unresolved'],p.http_trials.map(t=>[t.name,t.acceptable?'Accepted':'Rejected',number(t.source_records),number(t.on_time_records),number(t.late_records),number(t.unresolved_records)]),'Eight actual local trials · source outcomes preserved'));
   inspect(box,'Inspect actual failure observations and independent counts',result);box.append(origin('http/'+trial+'-result.json','Open original HTTP result'));
   if(['normal','transient-recovery'].includes(trial)){box.append(el('p','The download includes the original compressed independent receiver journal, encoded as base64 without changing its bytes. Offline validation checks its content identity, every recorded request count (including recovery GETs), and receipt hashes against exact control payloads.'));inspect(box,'Inspect journal source, encoding and blob hash',read('upstream.json').artifacts.find(a=>a.file==='http/'+trial+'-journal.txt'));}
   inspect(box,'Inspect recorded decision transitions',read('http-summary.json').transitions);wrapper.append(box);
  }};rerender=render;render();return wrapper;
 });return root;
}

