export function warehouseMetrics(read,metric){const p=read('projection.json');return [metric('Native event rows',number(p.native_row_counts.events),'Bounded public GA4 purchase-user cohort'),metric('Independent comparisons','5 / 5','Native row-count and multiset signatures match'),metric('Local dbt rowsets','5 / 5','Incremental, full and complete Python oracle'),metric('Regression faults detected','14 / 14','Old guard missed eight · native MERGE unexecuted')];}
export function warehousePanel(ui){const {el,json:read,facts,finding}=ui,{section,inspect,choose,table,origin,stages}=evidenceUI(ui),p=read('projection.json'),n=read('native.json'),local=read('local.json');const root=el('div',undefined,'warehouse-investigation release-investigation');const hero=el('div',undefined,'release-hero');hero.append(el('small','GA4 → BIGQUERY → SQL / DBT · SEPARATE EXECUTION LANES','release-kicker'),el('h2','Prove the grain before trusting the metric.'),el('p','Seven existing model SELECT bodies ran on BigQuery. Independent source results match five rowsets. Local dbt proves correction and replay behavior separately; native dbt build and MERGE remain unexecuted.'));root.append(hero);
 stages(root,[['native','01 · Native SQL comparison'],['local','02 · Local dbt correctness'],['guard','03 · Regression guard'],['boundary','04 · Identity & access boundaries']], 'native',stage=>{const box=section({native:'Native SQL and the source agree at their own grain.',local:'Late records and corrections must survive replay.',guard:'A passing guard can still miss the wrong facts.',boundary:'Snapshot identity is not correction identity.'}[stage]);
 function render(){box.replaceChildren(el('h3',{native:'Native SQL and the source agree at their own grain.',local:'Late records and corrections must survive replay.',guard:'A passing guard can still miss the wrong facts.',boundary:'Snapshot identity is not correction identity.'}[stage],'panel-title'));
 if(stage==='native'){
  box.append(el('p','Google public obfuscated ecommerce shard 20210101: purchases plus same-day events for their pseudo-users. This is not the full day or the synthetic Evermere business. Sessions can be censored at slice boundaries.'));
  box.append(table(['Rowset','Modeled rows','Independent source rows','Multiset comparison'],read('model-results.json').map(r=>[r.model,number(Number(r.row_count)),number(Number(read('source-results.json').find(s=>s.model===r.model).row_count)),'Matching SHA-256']), 'Two independently executed native queries · duplicate multiplicity retained'));
  box.append(choose('Inspect a native rowset','warehouse-model',read('model-results.json').map(r=>[r.model,r.model]),model,v=>{model=v;render();}));
  inspect(box,'Inspect both exact result signatures',{models:read('model-results.json').find(r=>r.model===model),source:read('source-results.json').find(r=>r.model===model)});
  box.append(finding('4,828 item rows are not 4,828 purchases','The item relation includes non-purchase interactions. Separate event, item, purchase-quality, observed session and daily grains prevent fan-out from turning item rows into conversions.'));
  box.append(table(['Actual job ID','State','Processed bytes','Job-reported billed bytes'],read('jobs.json').map(j=>[j.job_id,j.state,number(Number(j.total_bytes_processed)),number(Number(j.total_bytes_billed))]),'Uncached SELECT jobs · billing-disabled sandbox · billed bytes are not an invoice'));
  inspect(box,'Inspect native model SELECT query',ui.text('bigquery/warehouse_models_preview.sql'));inspect(box,'Inspect independent raw-source query',ui.text('bigquery/warehouse_source_oracle.sql'));inspect(box,'Inspect provider metadata and query hashes',read('jobs.json'));box.append(origin('native.json','Open recorded native execution boundaries'));
 }else if(stage==='local'){
  box.append(el('p','A separate synthetic fixture executed on DuckDB/dbt. This is recorded local warehouse acceptance, not a dbt-BigQuery run. Five complete output rowsets matched both an independent full database and a Python source oracle.'));
  box.append(table(['Admission','Events','Purchase events','Item rows','Duplicate transaction flags','Revenue flags'],local.phases.map(r=>[r.admitted_batch,r.events,r.purchase_events,r.item_rows,r.quality_flags.duplicate_transaction_event_rows,r.quality_flags.item_revenue_discrepancies]),'Actual local dbt phases · anomalies retained'));
  box.append(facts([['Late historical event','ev06 · original older event date'],['Corrected purchase','ev03 · version 2 · $130 synthetic USD'],['Replay','Same batch leaves rowsets unchanged'],['Oracle scope','Every field, NULL and duplicate multiplicity'],['Independent databases','Incremental and separate full build']]));
  inspect(box,'Inspect complete local acceptance and source hashes',local);inspect(box,'Inspect actual incremental model SQL',ui.text('ga4_pipeline/models/fct_ga4_events.sql'));box.append(origin('local.json','Open executed complete-oracle record'));
 }else if(stage==='guard'){
  const guard=read('guard.json');box.append(el('p','The old one-way test checked only date, version, arrival and revenue. It missed changed identities, nulls and an extra fact. The corrected full outer join compares all normalized event fields.'));
  const faults=guard.observations.filter(r=>r.fault!=='none');box.append(choose('Inspect a regression fault','warehouse-fault',faults.map((r,i)=>[String(i),r.fault+' · '+JSON.stringify(r.value)]),/^\d+$/.test(fault)?fault:'0',v=>{fault=v;render();}));const selected=faults[Number(fault)||0];
